int array_sum_rec(int a[], int n) {
    if (n <= 0) return 0;
    return a[n - 1] + array_sum_rec(a, n - 1);
}

int array_sum_rec(int a[], int n) {
    if (n == 0) return 0;
    return array_sum_rec(a, n - 1) + a[n - 1];
}

int array_sum_rec(int a[], int n) {
    if (n <= 0) return 0;
    int rest = array_sum_rec(a, n - 1);
    return rest + a[n - 1];
}
